/**
 * Hands the project to another member, or clears the lead. This is not part of
 * a general metadata edit: it has its own permission, and the incoming lead
 * must themselves be allowed to update the project.
 */
export async function changeProjectLead(
  actor: Actor,
  input: ChangeProjectLeadInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCan(actor, "project:change_lead", projectResource(project));
  assertNotArchived("Project", project.id, project);

  if (input.leadId !== null) {
    const lead = await resolveActor(input.leadId, input.orgId);
    if (lead === null) {
      throw new NotFoundError("Member", input.leadId);
    }
    if (!can(lead, "project:update", projectResource(project))) {
      assertCan(lead, "project:update", projectResource(project));
    }
  }

  return projectRepo.updateProject({
    orgId: input.orgId,
    projectId: input.projectId,
    leadId: input.leadId,
  });
}

