import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import { NotFoundError } from "@/server/services/_support";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as projectService from "@/server/services/project-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

describe("changeProjectLead", () => {
  it("lets an admin set, and a lead clear, and rejects the rest", async () => {
    const tenant = await createTenant("leadchange", "growth");
    const other = await createTenant("leadother", "growth");
    const outsider = await userRepo.insertUser({
      email: "outsider@leadchange.test",
      name: "Outsider",
      passwordHash: "seed",
    });

    const updated = await projectService.changeProjectLead(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      leadId: tenant.userIds.member,
    });
    expect(updated.leadId).toBe(tenant.userIds.member);

    const cleared = await projectService.changeProjectLead(tenant.actors.member, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      leadId: null,
    });
    expect(cleared.leadId).toBeNull();

    await expect(
      projectService.changeProjectLead(tenant.actors.member, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        leadId: tenant.userIds.admin,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(
      projectService.changeProjectLead(tenant.actors.admin, {
        orgId: other.org.id,
        projectId: tenant.project.id,
        leadId: tenant.userIds.admin,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      projectService.changeProjectLead(tenant.actors.admin, {
        orgId: tenant.org.id,
        projectId: other.project.id,
        leadId: tenant.userIds.admin,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      projectService.changeProjectLead(tenant.actors.admin, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        leadId: outsider.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      projectService.changeProjectLead(tenant.actors.admin, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        leadId: other.userIds.member,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    const viewerMember = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    await memberRepo.archiveMember(tenant.org.id, viewerMember!.id);
    await expect(
      projectService.changeProjectLead(tenant.actors.admin, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        leadId: tenant.userIds.viewer,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      projectService.changeProjectLead(tenant.actors.owner, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        leadId: tenant.userIds.viewer,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    const stored = await projectRepo.findProjectById(tenant.org.id, tenant.project.id);
    expect(stored?.leadId).toBeNull();

    await projectRepo.updateProject({
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      leadId: tenant.userIds.member,
    });
    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      archiveIssues: false,
    });
    await expect(
      projectService.changeProjectLead(tenant.actors.admin, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        leadId: tenant.userIds.admin,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
    const archived = await projectRepo.findProjectById(tenant.org.id, tenant.project.id);
    expect(archived?.leadId).toBe(tenant.userIds.member);
  });

  it("rejects a viewer as the new lead and lets a viewer lead hand off", async () => {
    const tenant = await createTenant("leadviewer", "growth");

    await expect(
      projectService.changeProjectLead(tenant.actors.admin, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        leadId: tenant.userIds.viewer,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    const before = await projectRepo.findProjectById(tenant.org.id, tenant.project.id);
    expect(before?.leadId).toBe(tenant.userIds.owner);

    await projectRepo.updateProject({
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      leadId: tenant.userIds.viewer,
    });

    const handed = await projectService.changeProjectLead(tenant.actors.viewer, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      leadId: tenant.userIds.member,
    });
    expect(handed.leadId).toBe(tenant.userIds.member);
  });
});

